csui.define('d2/commands/open.plugins/impl/browser.plugin',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/utils/base',
  'd2/commands/download',
  'd2/utils/rest.linkrels',
  'json!csui/utils/commands/open.types.json'
], function (_, $, base, DownloadCommand, RestLinkrels, openMimeTypes) {
  'use strict';

  var config = window.csui.requirejs.s.contexts._.config.config['csui/utils/commands/open'] || {},
    mimeTypesFromPlugins = _.chain(navigator.plugins || []).map(function (plugin) {
      return _.chain(plugin).map(function (mimeType) {
        return mimeType.type;
      }).value();
    })
      .flatten()
      .compact()
      .invoke('toLowerCase')
      .value();

  config = _.extend({
    // from https://code.google.com/p/chromium/codesearch#chromium/src/net/base/mime_util.cc
    // and https://tools.ietf.org/html/rfc3023
    // and https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/MIME_types/Complete_list_of_MIME_types
    mimeTypesForOpen: openMimeTypes.mimeTypesForOpen,

    // Opening HTML and XML documents can be considered a security risk.
    forceDownloadForMimeTypes: [
      'text/html',
      'text/xml',
      'application/xml'
    ]
  }, config);

  config.mimeTypesForOpen = _.invoke(config.mimeTypesForOpen, 'toLowerCase');
  config.forceDownloadForMimeTypes = _.invoke(config.forceDownloadForMimeTypes, 'toLowerCase');

  // Extend the openable MIME types by plugins installed in the browser
  config.mimeTypesForOpen = _.chain(config.mimeTypesForOpen)
    .concat(mimeTypesFromPlugins)
    .unique()
    .invoke('toLowerCase')
    .value();

  function BrowserPlugin() {
  }

  BrowserPlugin.prototype.getUrl = function (node, options) {
    var deferred = $.Deferred();
    if (!options || !options.downloadLink) {
      deferred.reject('Missing download link');
    } else {
      deferred.resolve(options.downloadLink);
    }
    return deferred.promise();
  };

  BrowserPlugin.isSupported = function (node) {
    var mimeType = node.get('mime_type');

    // Apple mobile devices should always open items via browser tab except for items included in force download
    if (base.isAppleMobile()) {
      return mimeType ? config.forceDownloadForMimeTypes.indexOf(mimeType) < 0 : true;
    }

    if (mimeType) {
      mimeType = mimeType.toLowerCase();

      // Safari cannot stream audio/video without byte-range support on server, so we need to force download those
      if (base.isSafari() && (mimeType.indexOf('audio/') === 0 || mimeType.indexOf('video/') === 0)) {
        return false;
      }

      return config.mimeTypesForOpen.indexOf(mimeType) >= 0 &&
        config.forceDownloadForMimeTypes.indexOf(mimeType) < 0;
    }
  };

  return BrowserPlugin;
});
