csui.define('d2/utils/validator/base.content.upload.validator',[
    'nuc/lib/jquery',
    'nuc/lib/marionette',
], function ($, Marionette) {
    'use strict';

    var BaseContentUploadValidator = Marionette.Object.extend({
        constructor: function BaseContentUploadValidator(/*options*/) {
            Marionette.Object.prototype.constructor.apply(this, arguments);
        },

        validateUploadedContent: function (/*uploadedContentData*/) {
            return $.Deferred().resolve().promise();
        }
    });
    return BaseContentUploadValidator;
});