csui.define('d2/controls/form/fields/alpaca/alpd2radiofield',[
  'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone',
  'nuc/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite',
  'd2/controls/form/fields/d2radiofield.view',
  'nuc/utils/base', 'i18n!d2/controls/form/impl/nls/lang'
], function (_, $, Backbone, Marionette, Alpaca,
             RadioFieldView, base, lang) {
  'use strict';

  Alpaca.Fields.D2RadioField = Alpaca.Fields.RadioField.extend({
    constructor: function CsuiRadioField(container, data, options, schema, view,
                                         connector,
                                         onError) {
      this.base(container, data, options, schema, view, connector, onError);
    },

    getFieldType: function () {
      return 'd2radio';
    },

    getFieldViewClass: function () {
      return RadioFieldView;
    },

    isValidationParticipant: function () {
      var result = this.base();
      return result && !this.schema.disabled;
    },

    isRequired: function () {
      var result = this.base();
      return result && !this.schema.disabled;
    },

    setup: function () {
      var origData = this.data;
      this.base();

      if (origData !== this.data && this.isRequired() && (this.options.removeDefaultNone === true)) {
        //Alpaca defaulted to the first value from enum during setup. We clear that to original value
        this.data = origData;
      }
    },

    postRender: function (callback) {
      this.base(callback);
      this.showField();
      this.removeExtraDivs();
    },

    removeExtraDivs: function () {
      // find all the empty .binf-col-sm-9 siblings and remove them
      var colElements = this.fieldView.$el.closest('.binf-col-sm-9').siblings();
      colElements.each(function (index, element) {
        if (this.tagName === 'DIV' && this.className === 'binf-col-sm-9' && _.isNull(element.firstChild)) {
          element.parentNode.removeChild(element);
        }
      });
    },

    showField: function () {
      var collectionData = [];
      if (this.options.optionLabels) {
        collectionData = _.zip(this.schema['enum'], this.options.optionLabels, _.pluck(this.options.enum, "category")).map(
          function (cur) {
            return {id: cur[0], name: cur[1], category: cur[2]};
          });
      }

      var collection = new Backbone.Collection(collectionData),
        selection = {},
        hasValue = true;
      if (this.data !== null && this.data !== "") {
        selection = new Backbone.Model({
          id: this.data,
          name: collection.get(this.data) && collection.get(this.data).get('name')
        });
      } else {
        // TODO : do we need this? this is when no selected value? check this
        selection = new Backbone.Model({
          id: null,
          name: '<' + lang.selectFieldDefaultLabel + '>'
        });
      }

      // add an id to the <label> element like alpaca23Label
      var id4Label,
        labelElement = this.field.find('> label');

      if (labelElement && labelElement.length === 1) {
        id4Label = labelElement.attr('for') + "Label";
        labelElement.attr('id', id4Label);
      }

      // create csui field
      var id = this.id,
        fieldViewClass = this.getFieldViewClass();

      this.fieldView = new fieldViewClass({
        model: new Backbone.Model({
          data: this.data,
          options: this.options,
          schema: this.schema,
          id: id
        }),
        id: _.uniqueId(id), // wrapper <div>
        alpacaField: this,
        labelId: id4Label, // this will remain undefined if the label does not exist
        selected: selection,
        collection: collection,
        mode: this.options.mode,
        path: this.path,
        dataId: this.name,
        alpaca: {
          data: this.data,
          options: this.options,
          schema: this.schema
        },
        hasValue: hasValue
      });

      // replace alpaca control with empty div having same classes as control
      var $field = $('<div>').addClass('alpaca-control');
      this.getControlEl().replaceWith($field);

      // show our field in div
      this.region = new Marionette.Region({el: $field});
      this.region.show(this.fieldView);
    },

    setValueAndValidate: function (value, validate) {
      this.setValue(value);
      var bIsValid = true;
      if (validate) {
        bIsValid = this.validate();
        this.refreshValidationState(false);
      }
      return bIsValid;
    },

    _validator: function (callback) {
      var value = this.getValue();

      if (this.schema.required && value === "") {
        callback({
          "status": false,
          "message": "This field is required"
        });
      } else {
        callback({
          "status": true
        });
      }
    },

    validate: function () {
      var ret = this.base();
      this.validation = _.omit(this.validation, "invalidValueOfEnum");
      return ret;
    },

    setValue: function (value) {
      value === null ? this.base("") : this.base(value);
    },

    getValue: function () {
      return this.data;
    },

    focus: function () {
      this.fieldView.setFocus();
    },

    destroy: function () {
      this.base();
      if (this.region) {
        this.region.destroy();
      }
    }
  });

  Alpaca.registerFieldClass('d2radio', Alpaca.Fields.D2RadioField, 'bootstrap-csui');

  return Alpaca.Fields.D2RadioField;
});
