csui.define('d2/controls/facet.bar/impl/facet.bar.task.date.item.view',["module",
  "nuc/lib/jquery",
  "nuc/lib/underscore",
  "nuc/lib/marionette",
  "hbs!./facet.bar.date.item"
], function (module, $, _, Marionette, template) {

  var FacetBarTaskDateItemView = Marionette.ItemView.extend({

    className: 'd2-facet-item d2-task-facet-date-item',

    tagName: 'li',

    template: template,

    ui: {
      'item': '.d2-facet-item',
      'content': '.d2-facet-item-content'
    },

    events: {
      'click @ui.item': 'cancelClick',
      'click @ui.content': 'cancelClick'
    },

    constructor: function FacetBarTaskDateItemView() {
      Marionette.ItemView.prototype.constructor.apply(this, arguments);
    },

    cancelClick: function (event) {
      // there is a href="#" set on the a-tag to let the browser make the facet item accessible
      // by keyboard. Don't let the event do anything, because it would let the browser to
      // navigate to the landing page.
      if (!$(event.target).hasClass('d2-icon-chiclet-close')) {
        event.preventDefault();
        event.stopPropagation();
      }
    }
  });

  return FacetBarTaskDateItemView;
});
