csui.define('d2/overrides/csui/utils/commands/open.node.perspective',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/utils/commandhelper',
  'csui/utils/commands/open.node.perspective',
  'csui/controls/form/pub.sub'
], function (require, $, _, CommandHelper, OpenNodePerspectiveCommand, PubSub) {
  'use strict';

  OpenNodePerspectiveCommand.prototype.execute = function (status, options) {
    var deferred = $.Deferred();
    csui.require([
      'csui/utils/contexts/factories/next.node',
      'd2/utils/contexts/factories/node.navigation',
      'd2/utils/contexts/context.controller',
      'd2/utils/node.utils'
    ], function (NextNodeModelFactory, NodeNavigationCollectionFactory, D2ContextController, NodeUtils) {
      var context = status.context || options && options.context,
        nextNode = context.getModel(NextNodeModelFactory),
        node = CommandHelper.getJustOneNode(status);
      // DTWO-108724 -- Needed this flag here so that in node.mixin.js, menu actions can be fetched properly.
      nextNode._fetchMenuNewObjectItems = true;
      var view = options && options.originatingView;
      if (context.isEmbeddedMode && !context.isFolderBrowser) {
        // Handle embedded mode clicks on "Location" columns in widgets other than folder browser.
        // For folder browser, the existing CSUI widget handles navigation via nextNode model
        context.currentNodeId = node.get('id');
        window.location.hash = '#d2?mode=folderbrowser&allow_back=true&folder_id=' + context.rootNodeId ;
      } else {
        //View State Model Porting
        var viewState = context.viewStateModel.get('state');
        if (viewState) {
          context.viewStateModel.set('state', _.omit(viewState, 'filter'), {silent: true});
        }
        // The nodestable uses this event to remove the order_by from the viewStateModel
        nextNode.trigger('before:change:id', node, view);

        if (view) {
          D2ContextController.setWidgetInfo(view);
        } else {
          D2ContextController.removeWidgetInfo(); //DTWO-51770 If view context is not present at all try opening with default Doclist
        }
        if(options && options.selectionNode){
          NodeUtils.setHighlightNode(options.selectionNode);
        }
        if(nextNode.attributes.id == node.get('id')){
          PubSub.trigger('d2:highlight:node');
        }else{
          nextNode.set({
            id: node.get('id')
          });
          // Set home cabinet flag separately because framework code blanks out all attributes of nextNode on setting id
          nextNode.set({
            _is_home_cabinet: node.get('_is_home_cabinet')
          });

          // Add to exisiting node navigation path
          var navigationCollection = context.getCollection(NodeNavigationCollectionFactory);
          navigationCollection.add({'id': node.get('id'), 'name': node.get('name')});
          if(context.isEmbeddedMode){
            context.visitedNodeHistory.push(node.get('id'));
          }
        }
      }
      deferred.resolve();
    }, function (error) {
      deferred.reject(error);
    });
    return deferred.promise();
  };

});
