csui.define('d2/widgets/advanced.search.results/search.facets',[
  'csui/models/facets'
], function (FacetCollection) {
  'use strict';

  var SearchFacetCollection = FacetCollection.extend({
    constructor: function SearchFacetCollection(/*models, options*/) {
      FacetCollection.prototype.constructor.apply(this, arguments);
    },
    ensureFetched: function (/*options*/) {
      // Dummy method , we fetch facets along with results, its not a seperate fetch call
      // this method is not relevant for smart view , but we add it since  csui uses it in search results
      return true;
    },

  });

  return SearchFacetCollection;
});