csui.define('d2/controls/form/fields/alpaca/alpd2singleselecttreefield',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/marionette',
  'nuc/lib/backbone',
  'csui/controls/form/fields/alpaca/alpcsuitextfield',
  'csui/lib/alpaca/js/alpaca.lite',
  'd2/controls/form/fields/d2singleselecttreefield.view'
], function ($, _, Marionette, Backbone, AlpacaCsuiTextField, Alpaca, D2SingleSelectTreeFieldView) {
  'use strict';

  Alpaca.Fields.D2SingleSelectTreeField = Alpaca.Fields.CsuiTextField.extend({
    constructor: function CsuiTextField(container, data, options, schema, view, connector,
                                        onError) {
      this.base(container, data, options, schema, view, connector, onError);
    },

    getFieldType: function () {
      return 'd2singleselecttreefield';
    },

    getValue: function () {
      return this.fieldView.getValue();
    },

    showField: function () {

      var id = this.id;

      // add an id to the <label> element like alpaca23Label
      var id4Label, id4Description = this.options ? this.options.descriptionId : '',
        labelElement             = $(this.field[0]).find('label');

      if (labelElement && labelElement.length===1) {
        id4Label = labelElement.attr('for') + "Label";
        labelElement.attr('id', id4Label);
      }

      // our field
      this.fieldView = new D2SingleSelectTreeFieldView({
        model: new Backbone.Model({
          data: this.data,
          options: this.options,
          schema: this.schema,
          inputType: 'text',
          id: id // <input type=text
        }),
        id: _.uniqueId(id), // wrapper <div>
        alpacaField: this,
        labelId: id4Label,
        descriptionId: id4Description,
        value: this.data,
        readonly: true,
        dataId: this.name,
        path: this.path,
        alpaca: {
          data: this.data,
          options: this.options,
          schema: this.schema
        }
      });

      // replace alpaca control with empty div having same classes as control
      var $field = $('<div>').addClass('alpaca-control');
      this.getControlEl().replaceWith($field);

      // show our field in div
      this.region = new Marionette.Region({el: $field});
      this.region.show(this.fieldView);

      return;
    }
  });

  Alpaca.registerFieldClass('d2singleselecttreefield', Alpaca.Fields.D2SingleSelectTreeField, 'bootstrap-csui');
  return Alpaca.Fields.D2SingleSelectTreeField;
});