csui.define('d2/models/table/column.collection',[
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'i18n!csui/models/widget/nls/lang'
], function(_, Backbone, lang){
  'use strict';

  /**
   * A generic Column collection. Used in the context of a {@link ../mixins/browsable.collection.mixin|BrowsableMixin} to contain and define column definitions for a table like view.
   *
   * @module {d2/sdk/models/table/column.collection} d2/sdk/models/table/"column.collection"
   * @name ColumnCollection
   * @extends {external:Backbone.Collection}
   *
   */

  /**
   * @external "Backbone.Model"
   * @see https://backbonejs.org/#Model
   */

  /**
   * @external "Backbone.Collection"
   * @see https://backbonejs.org/#Collection
   */

  var ColumnModel = Backbone.Model.extend({
    idAttribute: null,

    constructor: function ColumnModel(attributes, options) {
      if (attributes && !attributes.title) {
        attributes.title = lang[attributes.column_key];
      }
      ColumnModel.__super__.constructor.call(this, attributes, options);
    }
  });

  var ColumnCollection = Backbone.Collection.extend({
    model: ColumnModel,

    resetCollection: function (response, options) {
      var columns, me = this;
      if (response && response.columns) {
        // columns from server
        columns = _.map(response.columns, function (column) {
          return new me.model(column);
        });
      }
      this.reset(columns, options);
      this.fetched = true;
    }
  });

  return ColumnCollection;
});