csui.define('d2/overrides/csui/utils/commands/filter',[
  'nuc/lib/underscore',
  'csui/utils/commands/filter',
  'dctmw/server.adaptors/converters/node',
  'd2/utils/constants',
], function (_, FilterCommand, nodeConverter, Constants) {
  'use strict';

  var proto = FilterCommand.prototype,
    origEnabled = proto.enabled;

  proto.enabled = function (status/*, options*/) {
    var container = status.container,
      view = status.originatingView;
    if (status.toolItem && status.toolItem.get('tasksFilter') === true) {
      return true;
    }

    if(container?.get("type")===Constants.Types.COLLECTIONS){
      return true;
    }

    if (container && nodeConverter.isNonDCTMNode(container)) {
      return false;
    }
    if (view && view.collection && (_.isEmpty(view.collection.facetConfig) && view.collection?.avaliableD2FilterConfigFacets?.topics?.length===0)) {
      return false;
    }

    return origEnabled.apply(this, arguments);
  };

});
