csui.define('d2/commands/node.progress.command',[
  'module',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'csui/models/fileuploads',
  'd2/controls/globalmessage/globalmessage',
  'csui/utils/commands/node',
  'csui/utils/commandhelper',
  'csui/utils/command.error',
  'csui/utils/nodesprites',
  'd2/controls/globalmessage/impl/progresspanel/node.creation.success.message.view',
  'dctmw/utils/utils',
  'd2/utils/concurrency.manager',
], function (module, $, _, Backbone, UploadFileCollection, GlobalMessage, NodeCommand, CommandHelper, CommandError, NodeSprites,
             NodeCreationSuccessMessageView, utils, ConcurrencyManager) {
  'use strict';

  var config = module.config();
  _.defaults(config, {
    parallelism: 3
  });

  var PageLeavingBlocker;

  return NodeCommand.extend({

    execute: function (status, options) {
      options = options || {};

      // Avoid messages from handleExecutionResults. We use our own evaluation here and show message.
      status.suppressFailMessage = true;
      status.suppressSuccessMessage = true;

      if (utils.isMobile()) {
        if (status.originatingView && !status.originatingView.blockActions) {
          status.originatingView = status.originatingView._parent;
        }
        options.disableConcurrentProcess = true;
      }

      var me = this, deferred = $.Deferred();

      if(options.disableConcurrentProcess !== true){
        /* When concurreny is enabled for the command,
         * If object is already is in progress state, then further action cannot be performed.
         */
        if (ConcurrencyManager.isProcessPending(CommandHelper.getAtLeastOneNode(status))) {
          return $.Deferred().resolve().promise();
        }
        /*On minimize of progress panel, the command execute promise will be resolved.*/
        ConcurrencyManager.listenForProcessMinimize(status, options, this).done(deferred.resolve);
      }

      this.preProcess(status, options).done(function () {
        _.defaults(options, status); // Pass status values as options to all implementation methods
        options.parallelism = me.get('parallelism') || 1;
        me._performActions(status, options).done(deferred.resolve).fail(deferred.reject);
      }).fail(function (error) {
        if (error) {
          GlobalMessage.showMessage('error', error.message || error);
        }
        deferred.reject(error);
      });
      return deferred.promise();
    },

    _performActions: function (status, options) {
      var me = this,
        deferred = $.Deferred(),
        nodes = CommandHelper.getAtLeastOneNode(status);

      if (!nodes || !nodes.length) {
        return deferred.reject(new CommandError('At least one node must be present')).promise();
      }

      var queueItems = nodes.map(function (node, index) {
          return {
            name: node.get('name'),
            state: index < options.parallelism ? 'processing' : 'pending',
            count: 0,
            total: 1,
            node: node,
            doneCommand: options.doneCommand,
            commandContainer: options.commandContainer,
            context: options.context,
            originatingView: options.originatingView,
            actionType: "NODEPROGRESS-" + _.uniqueId(),
          };
        }),
        enableCancel = options.enableCancel !== undefined ? options.enableCancel : true,
        collection = new UploadFileCollection(queueItems, {connector: nodes.at(0).connector}),
        newStatus = _.defaults({nodes: collection}, status, options),
        suppressProgress = (status.toolItem && status.toolItem.get('suppressProgress')) || options.suppressProgress,
        msgOpts = _.extend({
          enableCancel: enableCancel,
          originatingView: options.originatingView,
          commandContainer: status.container,
          context: status.context
        }, me.getMessageOptions(options));

      collection.each(function (item) {
        item.node = item.get('node');
        /**
         * DTWO-106693: Progresspanel was setting the container attribute as false if the mime_type attribute is not defined which was done by SMart
         * inorder to handle that we are setting the type attribute to mime_type(same is done by SMart folks as well)
         */
        item.node.set("mime_type", item.node.get("mime_type") === undefined ? item.node.get("type") : item.node.get("mime_type"));
        item.unset('node');
      });

      if (!suppressProgress) {
        options.progressPanel = true;
        // The framework requires the targetLocation property in the Backbone model for single object operations. This property serves the following purposes:
        // 1. For single object operations, the progress panel will automatically close after 5 seconds if no 'go to overview' or 'locate' actions are performed.
        // 2. The framework tracks this behavior using the targetLocation flag at the model level.
        options.targetLocation && collection.length === 1 && collection.at(0).set('targetLocation', true);
        options.progressPanelView = GlobalMessage.showProgressPanel(collection, msgOpts);
      }

      // do not display our result messages in _performActions
      newStatus.suppressMultipleSuccessMessage = true;
      newStatus.suppressMultipleFailMessage = true;

      var postExecute = function (results) {

        var failedCnt = 0, successCnt = 0,
          hideFailureMessage = options.hideFailureMessage === true;

        _.each(results, function (result) {
          (result instanceof Backbone.Model) ? ++successCnt : ++failedCnt;
        });

        options.multiFileAllFailed = (successCnt === 0 && failedCnt > 1);
        var opts = me.getMessageOptions(options);

        if (!failedCnt) {
          me._showSuccessMessage(results, options);
        } else if (suppressProgress && !hideFailureMessage) {
          me._showFailureMessage(results, collection, options, _.extend(msgOpts, opts));
        }

        var handleOutput = me.handleResults(results, options, collection);
        if (!handleOutput || !_.isFunction(handleOutput.then)) {
          handleOutput = $.Deferred().resolve().promise();
        }

        handleOutput.done(function () {
          // Reject promise in case there was any failure (even if handleResults passes)
          if (failedCnt > 0) {
            deferred.reject(results);
          } else {
            deferred.resolve(results);
          }
        }).fail(deferred.reject);
      };
      me._processItems(newStatus, options).done(postExecute).fail(postExecute);

      return deferred.promise();
    },

    _processItems: function (status, options) {
      var deferred = $.Deferred(),
        self = this,
        promises;
      csui.require(['csui/utils/taskqueue', 'csui/utils/page.leaving.blocker'
      ], function (TaskQueue) {
        PageLeavingBlocker = arguments[1];
        options = options || {};
        if (!options.context) {
          options.context = status.context;
        }
        self._announceStart(status);
        var nodes = CommandHelper.getAtLeastOneNode(status),
          queue = new TaskQueue({
            parallelism: options.parallelism || config.parallelism
          });

        promises = nodes.map(function (node/*, index*/) {
          var deferred = $.Deferred();
          queue.pending.add({
            worker: function () {
              _.isFunction(self.preExecute) && self.preExecute(node);
              self._performAction(node, options)
                .done(function (args) {
                  _.isFunction(self.postExecute) && self.postExecute(status, args);
                  deferred.resolve(args);
                })
                .fail(function (error) {
                  deferred.reject(error);
                });
              return deferred.promise();
            }
          });
          return deferred.promise();
        });

        // return a promise that has an array with results of original promises
        $.whenAll
          .apply($, promises)
          .always(_.bind(self._announceFinish, self, status))
          .done(function () {
            if (!status.suppressMultipleSuccessMessage) {
              self.showSuccess(promises);
            }
            deferred.resolve.apply(deferred, arguments);      // pass the original arguments to handler, so that events are triggered
          })
          .fail(function () {
            if (!status.suppressMultipleFailMessage) {
              self.showError(promises);
            }
            deferred.reject.apply(deferred, arguments);      // pass the original arguments to handler, so that events are triggered
          });

      }, function (error) {
        deferred.reject(error);
      });
      return deferred.promise();
    },

    _announceStart: function (status) {
      if (!status.deleteBlockAction) {
        var originatingView = status.originatingView;
        if (originatingView && originatingView.blockActions) {
          originatingView.blockActions();
        }
        var pageLeavingWarning = this.get('pageLeavingWarning');
        if (pageLeavingWarning) {
          PageLeavingBlocker.enable(pageLeavingWarning);
        }
      }
      this._setViewStateModelMultiItemOperationStatus(status.context, true);
    },

    _announceFinish: function (status) {
      this._setViewStateModelMultiItemOperationStatus(status.context, false);

      if (this.get('pageLeavingWarning')) {
        PageLeavingBlocker.disable();
      }
      var originatingView = status.originatingView;
      if (originatingView && originatingView.unblockActions) {
        originatingView.unblockActions();
      }
    },

    _performAction: function (model, options) {
      var deferred = $.Deferred(), state = model.get('state');

      if (state === 'aborted' || state === 'stopped') {
        model.set('count', 1);
        model.deferred.reject(model);
        deferred.reject();
      } else {
        var node = model.node;
        this.doAction(node, options).done(function () {
          model.set({
            count: 1,
            state: 'resolved'
          });
          model.deferred.resolve(model);
          deferred.resolve(node);
        }).fail(function (err) {
          if (err.responseText) {
            err = utils.parseAjaxErrorAsString(err);
          }
          var cmdError = new CommandError(err);
          model.set({
            count: 1,
            state: 'rejected',
            errorMessage: err
          });
          model.deferred.reject(model, cmdError);
          deferred.reject(cmdError);
        });
      }

      return deferred.promise();
    },

    _showSuccessMessage: function (results, options) {
      var hideSuccessMessage = options.hideSuccessMessage === true,
          msgOpts = this.getMessageOptions(options);
      if (results.length === 1) {
        if (!hideSuccessMessage) {
          var node = results[0],
            inSameContainer = this._isNodeInContainer(node, options.commandContainer);
          if(options.progressPanelView === undefined && inSameContainer){
            const msg = _.str.sformat(msgOpts.oneFileSuccess, node.get('name'))
            GlobalMessage.showMessage('success', msg);
          }
        }
      }
    },

    _showFailureMessage: function (results, collection, options, msgOpts) {
      options.progressPanel = true;
      options.progressPanelView = GlobalMessage.showProgressPanel(collection, msgOpts);
    },

    _isNodeInContainer: function (node, container) {
      if (node && container) {
        var parentIds = node.get('i_folder_id') || [];
        return _.contains(parentIds, container.get('id'));
      }
      return true;
    },

    /**
     * Implementation class can use this method to perform any checks before actual action is executed. It must return
     * a promise. If it is resolved, then action will be executed, else it will be canceled.
     */
    preProcess: function (/*status, options*/) {
      return $.Deferred().resolve().promise();
    },

    /**
     * Implementation class must implementation this method to perform the actual action on a given node. It should
     * resolve the returned promise with a node object (normally original node object with some updates).
     */
    doAction: function (/*node, options*/) {
      return $.Deferred().reject('Implementation required by subclass').promise();
    },

    /**
     * If this method returns a promise, then command will be resolved only after this promise is resolved. "results"
     * argument is an array containing one element for each input node. The element will be:
     *    - Node object, if action for that node was successful
     *    - undefined, if action was aborted by user for that node
     *    - All other cases, it is error in execution, and element will be whatever doAction promise was "rejected" with
     */
    handleResults: function (/*results, options*/) {
    },

    /**
     * Following message keys are supported. Implementation should return these as required:
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | Lang Key                               | No. of | * | Status                              | Params to the message        |
     * |                                        | items  |   |                                     |                              |
     * +========================================+========+===+=====================================+==============================+
     * | oneFilePending                         | Single |   | In process                          | {0} - Item name              |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | oneFileSuccess                         | Single |   | Success                             | {0} - Successful item name   |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | oneFileFailure                         | Single |   | Failure                             | {0} - Failed item name       |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | multiFilePending                       | Multi  |   | In process                          | {0} - Total items count      |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | multiFileSuccess                       | Multi  |   | Success                             | {0} - Successful items count |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | multiFileOneFailure                    | Multi  |   | Single item failed                  | None                         |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | multiFileFailure                       | Multi  |   | Multiple items failed               | {0} - Failed items count     |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | oneFileFailureOneFileSuccess           | Multi  | * | 1 failed, 1 succeeded               | None                         |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | multipleFileFailureOneFileSuccess      | Multi  | * | Multiple failed, 1 succeeded        | {0} - Failed items count     |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | oneFileFailureMultipleFileSuccess      | Multi  | * | 1 failed, multiple succeeded        | {0} - Total items count      |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | multipleFileFailureMultipleFileSuccess | Multi  | * | Multiple failed, multiple succeeded | {0} - Failed items count     |
     * |                                        |        |   |                                     | {1} - Successful items count |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     * | someItemsStopped                       | Multi  |   | User stops one or more items        | {0} - Total items count      |
     * +----------------------------------------+--------+---+-------------------------------------+------------------------------+
     *   Items marked "*" are applicable only if "suppressProgress" option is true. In such case, it will show toast
     *   message according to these message config.
     */
    getMessageOptions: function (/*options*/) {
      return {};
    }

  });

});
