csui.define('d2/models/export.status',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'd2/models/zip.status',
  'i18n!d2/utils/job.tracker/impl/nls/lang'
], function(_, $, Backbone, ZipStatus, lang){

  return ZipStatus.extend({
    getHeaderTitle: function(){
      var headerTitle;
      switch(this.get('status')){
        case 'COMPLETED':
          headerTitle = lang.ExportCompletedHeaderTitle;
          break;
        case 'INPROGRESS':
          headerTitle = lang.ExportProcessingHeaderTitle;
          break;
        case 'CANCELLED':
          headerTitle = lang.ExportAbortedTitle;
          break;
        default:
          headerTitle = lang.ExportProcessingHeaderTitle;
      }

      return headerTitle;
    },
  })

});